select case when orders.amount >= 1670 then 'high' when orders.amount >= 560 then 'mid' else 'low' end as amount_bucket, orders.customer_id, concat_ws(', ', sort_array(collect_set(payments.method))) as method_values, round((100 * sum(case when payments.method = 'paypal' then 1 else 0 end)) / count(*), 1) as pct_paypal from payments inner join orders on payments.order_id = orders.id where orders.amount > 470 group by case when orders.amount >= 1670 then 'high' when orders.amount >= 560 then 'mid' else 'low' end, orders.customer_id
